<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$user=requireLogin();require_once BASE_PATH.'/includes/rental-operations-common.php';ro_require_permission('inspections.manage');
$pdo=Database::connection();$inspectionId=(int)($_GET['inspection_id']??$_POST['inspection_id']??0);$rentalId=(int)($_GET['rental_id']??$_POST['rental_id']??0);$errors=[];
$uploadImages=static function(PDO $pdo,int $inspectionId):void{
    if(empty($_FILES['images'])||!is_array($_FILES['images']['name']??null))return;
    $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$dir=BASE_PATH.'/uploads/inspection-images';
    if(!is_dir($dir)&&!mkdir($dir,0750,true)&&!is_dir($dir))throw new RuntimeException('Could not create the inspection image directory.');
    $count=count($_FILES['images']['name']);$finfo=new finfo(FILEINFO_MIME_TYPE);
    for($i=0;$i<$count;$i++){
        $err=$_FILES['images']['error'][$i]??UPLOAD_ERR_NO_FILE;if($err===UPLOAD_ERR_NO_FILE)continue;if($err!==UPLOAD_ERR_OK)throw new RuntimeException('One of the images failed to upload.');
        $tmp=$_FILES['images']['tmp_name'][$i]??'';$size=(int)($_FILES['images']['size'][$i]??0);if($size<1||$size>5*1024*1024)throw new RuntimeException('Each image must be smaller than 5 MB.');
        $mime=$finfo->file($tmp);if(!isset($allowed[$mime]))throw new RuntimeException('Only JPG, PNG, or WebP images are allowed.');
        $name='inspection-'.$inspectionId.'-'.bin2hex(random_bytes(12)).'.'.$allowed[$mime];$path=$dir.'/'.$name;if(!move_uploaded_file($tmp,$path))throw new RuntimeException('Could not save an uploaded image.');
        $relative='uploads/inspection-images/'.$name;$desc=trim((string)($_POST['image_description']??''));$pdo->prepare('INSERT INTO inspection_images (inspection_id,image_path,description) VALUES (?,?,?)')->execute([$inspectionId,$relative,$desc?:null]);
    }
};
if(is_post()){
    ro_post_guard();
    try{
        if(isset($_POST['upload_images'])){if(!$inspectionId)throw new RuntimeException('Save the inspection before uploading images.');$uploadImages($pdo,$inspectionId);ro_flash('success','Inspection images uploaded.');redirect('admin/inspection-form.php?inspection_id='.$inspectionId);}
        $type=(string)($_POST['inspection_type']??'damage_followup');if(!in_array($type,['routine','damage_followup'],true))throw new RuntimeException('Select a valid inspection type.');
        $stmt=$pdo->prepare('SELECT rental_id,vehicle_id FROM rentals WHERE rental_id=?');$stmt->execute([$rentalId]);$rental=$stmt->fetch(PDO::FETCH_ASSOC);if(!$rental)throw new RuntimeException('Rental not found.');
        $mileage=($_POST['odometer_reading']??'')!==''?(int)$_POST['odometer_reading']:null;$fuel=($_POST['fuel_level_percent']??'')!==''?(float)$_POST['fuel_level_percent']:null;if($mileage!==null&&$mileage<0)throw new RuntimeException('Mileage must be non-negative.');if($fuel!==null&&($fuel<0||$fuel>100))throw new RuntimeException('Fuel level must be between 0 and 100.');
        $inspectionTime = trim((string)($_POST['inspected_at'] ?? ''));
        if ($inspectionTime !== '') { $inspectionTime = (new DateTimeImmutable($inspectionTime))->format('Y-m-d H:i:s'); } else { $inspectionTime = date('Y-m-d H:i:s'); }
        $stmt=$pdo->prepare('INSERT INTO vehicle_inspections (rental_id,vehicle_id,inspected_by,inspection_type,inspected_at,odometer_reading,fuel_level_percent,exterior_condition,interior_condition,cleanliness,damage_notes,other_notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');
        $stmt->execute([$rentalId,$rental['vehicle_id'],isset($user['user_id'])?(int)$user['user_id']:null,$type,$inspectionTime,$mileage,$fuel,($_POST['exterior_condition']??'')?:null,($_POST['interior_condition']??'')?:null,($_POST['cleanliness']??'')?:null,trim((string)($_POST['damage_notes']??''))?:null,trim((string)($_POST['other_notes']??''))?:null]);$inspectionId=(int)$pdo->lastInsertId();
        RentalOperations::logEvent($pdo,isset($user['user_id'])?(int)$user['user_id']:null,'inspection.created','vehicle_inspection',(string)$inspectionId,'Vehicle inspection recorded',null,['rental_id'=>$rentalId,'inspection_type'=>$type,'odometer_reading'=>$mileage,'fuel_level_percent'=>$fuel]);
        $uploadImages($pdo,$inspectionId);ro_flash('success','Inspection saved. Uploads are linked to the inspection record.');redirect('admin/inspection-form.php?inspection_id='.$inspectionId);
    }catch(Throwable $e){ro_flash('danger',$e->getMessage());redirect($inspectionId?'admin/inspection-form.php?inspection_id='.$inspectionId:'admin/inspection-form.php?rental_id='.$rentalId);}
}
$inspection=null;if($inspectionId){$stmt=$pdo->prepare('SELECT vi.*,r.rental_number,v.make,v.model,v.registration_no FROM vehicle_inspections vi JOIN rentals r ON r.rental_id=vi.rental_id JOIN vehicles v ON v.vehicle_id=vi.vehicle_id WHERE vi.inspection_id=?');$stmt->execute([$inspectionId]);$inspection=$stmt->fetch(PDO::FETCH_ASSOC);if(!$inspection){http_response_code(404);exit('Inspection not found.');}$rentalId=(int)$inspection['rental_id'];}
$rental=null;if($rentalId){$stmt=$pdo->prepare('SELECT r.rental_id,r.rental_number,r.vehicle_id,v.make,v.model,v.registration_no FROM rentals r JOIN vehicles v ON v.vehicle_id=r.vehicle_id WHERE r.rental_id=?');$stmt->execute([$rentalId]);$rental=$stmt->fetch(PDO::FETCH_ASSOC);}if(!$inspection&&!$rental){http_response_code(400);exit('Choose a rental first.');}
$images=[];if($inspection){$stmt=$pdo->prepare('SELECT * FROM inspection_images WHERE inspection_id=? ORDER BY inspection_image_id DESC');$stmt->execute([$inspectionId]);$images=$stmt->fetchAll(PDO::FETCH_ASSOC);}
$pageTitle=$inspection?'Inspection details':'New inspection';$currentPage='inspections';require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/rental-operations-nav.php';
?>
<div class="ro-shell"><div class="ro-page-heading"><div><a class="ro-back-link" href="<?= e(base_url('admin/rental-view.php?id='.$rentalId)) ?>"><i class="bi bi-arrow-left"></i> Back to rental</a><h1><?= $inspection?'Inspection record':'New vehicle inspection' ?></h1><p><?= e($rental['rental_number']??$inspection['rental_number']) ?> · <?= e(($rental['make']??$inspection['make']).' '.($rental['model']??$inspection['model']).' · '.($rental['registration_no']??$inspection['registration_no'])) ?></p></div><div class="ro-heading-symbol"><i class="bi bi-clipboard2-check"></i></div></div>
<?php if(!$inspection): ?><section class="ro-panel"><div class="ro-panel-head"><div><span class="ro-kicker">CONDITION RECORD</span><h2>Inspection details</h2></div></div><form method="post" enctype="multipart/form-data" class="ro-form-grid"><?= csrf_field() ?><input type="hidden" name="rental_id" value="<?= $rentalId ?>"><div class="ro-field"><label for="inspection_type">Inspection type *</label><select class="form-select" id="inspection_type" name="inspection_type" required><option value="damage_followup">Damage follow-up</option><option value="routine">Routine</option></select></div><div class="ro-field"><label for="inspected_at">Inspection time</label><input class="form-control" id="inspected_at" name="inspected_at" type="datetime-local" value="<?= e(date('Y-m-d\TH:i')) ?>"></div><div class="ro-field"><label for="odometer_reading">Odometer (km)</label><input class="form-control" id="odometer_reading" name="odometer_reading" type="number" min="0"></div><div class="ro-field"><label for="fuel_level_percent">Fuel level (%)</label><input class="form-control" id="fuel_level_percent" name="fuel_level_percent" type="number" min="0" max="100" step="0.01"></div><div class="ro-field"><label for="exterior_condition">Exterior</label><select class="form-select" id="exterior_condition" name="exterior_condition"><option value="">Not recorded</option><option value="excellent">Excellent</option><option value="good">Good</option><option value="fair">Fair</option><option value="poor">Poor</option></select></div><div class="ro-field"><label for="interior_condition">Interior</label><select class="form-select" id="interior_condition" name="interior_condition"><option value="">Not recorded</option><option value="excellent">Excellent</option><option value="good">Good</option><option value="fair">Fair</option><option value="poor">Poor</option></select></div><div class="ro-field"><label for="cleanliness">Cleanliness</label><select class="form-select" id="cleanliness" name="cleanliness"><option value="">Not recorded</option><option value="clean">Clean</option><option value="acceptable">Acceptable</option><option value="needs_cleaning">Needs cleaning</option></select></div><div class="ro-field"><label for="images">Evidence photos (optional)</label><input class="form-control" id="images" name="images[]" type="file" accept="image/jpeg,image/png,image/webp" multiple><small class="text-secondary">JPG, PNG or WebP; up to 5 MB each.</small></div><div class="ro-field ro-field-full"><label for="damage_notes">Damage notes</label><textarea class="form-control" id="damage_notes" name="damage_notes" rows="3"></textarea></div><div class="ro-field ro-field-full"><label for="other_notes">Other notes</label><textarea class="form-control" id="other_notes" name="other_notes" rows="3"></textarea></div><div class="ro-form-actions"><button class="btn ro-btn-primary" type="submit"><i class="bi bi-check2-circle me-1"></i> Save inspection</button></div></form></section>
<?php else: ?><section class="ro-panel"><div class="ro-panel-head"><div><span class="ro-kicker">SAVED RECORD</span><h2><?= e(ucwords(str_replace('_',' ',$inspection['inspection_type']))) ?> inspection</h2></div><?= ro_status_badge($inspection['inspection_type']) ?></div><div class="ro-detail-list"><div><span>Inspected at</span><strong><?= e(ro_date($inspection['inspected_at'])) ?></strong></div><div><span>Odometer</span><strong><?= $inspection['odometer_reading']===null?'—':number_format((int)$inspection['odometer_reading']).' km' ?></strong></div><div><span>Fuel level</span><strong><?= $inspection['fuel_level_percent']===null?'—':e((string)$inspection['fuel_level_percent']).'%' ?></strong></div><div><span>Exterior</span><strong><?= e($inspection['exterior_condition']?:'Not recorded') ?></strong></div><div><span>Interior</span><strong><?= e($inspection['interior_condition']?:'Not recorded') ?></strong></div><div><span>Cleanliness</span><strong><?= e($inspection['cleanliness']?:'Not recorded') ?></strong></div><div class="ro-detail-full"><span>Damage notes</span><p><?= nl2br(e($inspection['damage_notes']?:'None recorded')) ?></p></div><div class="ro-detail-full"><span>Other notes</span><p><?= nl2br(e($inspection['other_notes']?:'None recorded')) ?></p></div></div></section><section class="ro-panel mt-4"><div class="ro-panel-head"><div><span class="ro-kicker">PHOTO EVIDENCE</span><h2>Inspection images</h2></div></div><?php if($images): ?><div class="ro-image-grid"><?php foreach($images as $img): ?><figure><a href="<?= e(base_url($img['image_path'])) ?>" target="_blank" rel="noopener"><img src="<?= e(base_url($img['image_path'])) ?>" alt="<?= e($img['description']?:'Vehicle inspection photo') ?>"></a><figcaption><?= e($img['description']?:'Inspection evidence') ?></figcaption></figure><?php endforeach; ?></div><?php else: ?><p class="text-secondary">No photos attached to this inspection yet.</p><?php endif; ?><form method="post" enctype="multipart/form-data" class="ro-upload-row"><?= csrf_field() ?><input type="hidden" name="inspection_id" value="<?= $inspectionId ?>"><input type="file" class="form-control" name="images[]" accept="image/jpeg,image/png,image/webp" multiple required><input type="text" class="form-control" name="image_description" maxlength="255" placeholder="Photo description (optional)"><button class="btn ro-btn-primary" name="upload_images" value="1" type="submit"><i class="bi bi-upload me-1"></i> Upload</button></form></section><?php endif; ?></div>
<?php require BASE_PATH.'/includes/footer.php'; ?>
